import {
  ChangeDetectionStrategy,
  Component,
  inject,
  signal,
} from "@angular/core";

import { ButtonModule } from "primeng/button";
import { DialogModule } from "primeng/dialog";
import { InputTextModule } from "primeng/inputtext";

import {
  FormControl,
  FormGroup,
  ReactiveFormsModule,
  Validators,
} from "@angular/forms";
import { User, userStore } from "@app/store/userStore";

const primengModules = [ButtonModule, DialogModule, InputTextModule];

@Component({
  selector: "app-create-edit-user-dialog",
  standalone: true,
  imports: [...primengModules, ReactiveFormsModule],
  templateUrl: "./create-edit-user-dialog.component.html",
  styleUrl: "./create-edit-user-dialog.component.css",
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CreateEditUserDialogComponent {
  userStore = inject(userStore);

  user = signal<User | null>(null);
  visible = signal<boolean>(false);
  userForm = signal(
    new FormGroup({
      username: new FormControl("", [Validators.required]),
      firstName: new FormControl("", [Validators.required]),
      lastName: new FormControl("", [Validators.required]),
    }),
  );

  loadUser(user: User) {
    this.user.set(user);
    this.userForm().patchValue({
      username: user.username,
      firstName: user.firstName,
      lastName: user.lastName,
    });
  }

  showCreateDialog() {
    this.user.set(null);
    this.userForm().reset();
    this.visible.set(true);
  }

  showDialog() {
    this.visible.set(true);
  }
}
