import { inject } from "@angular/core";
import { AdmUserService } from "@app/administration/services/adm-user.service";
import { signalStore, withState, withEntities, patchState, setAllEntities, updateEntity, removeEntity } from "@ngrx/signals";

export interface User {
  id: number;
  username: string;
  token: string;
  firstName: string;
  lastName: string;
  password: string;
  createdAt: string;
}

interface UserState {
  state: "loading" | "loaded" | "error";
}

const initialState: UserState = {
  state: "loading",
};

export const userStore = signalStore(
  { providedIn: "root" },
  withState(initialState),
  withEntities<User>(),
  withMethods((store, userService = inject(AdmUserService)) => ({
    setUsers(users: User[]): void {
      patchState(store, setAllEntities(users));
      patchState(store, { state: "loaded" });
    },
    loadUsers(): void {
      patchState(store, { state: "loading" });
      userService.fetchUsers().subscribe({
        next: (resp) => {
          patchState(store, setAllEntities(resp));
          patchState(store, { state: "loaded" });
        },
      });
    },
    addUser(user: Omit<User, "id" | "token">): void {
      const tempId = Date.now();
      const tempUser = { ...user, id: tempId, token: "" };
      patchState(store, addEntities([tempUser]));
      userService.addUser(tempUser).subscribe({
        next: (newUser) => {
          patchState(store, updateEntity({ id: tempId, changes: newUser }));
        },
        error: (err) => {
          patchState(store, removeEntity(tempId));
        },
      });
    },
    updateUser(user: Partial<User> & { id: number }) {
      const originalUser = store.entities().find((u) => u.id === user.id);
      if (!originalUser) return;
      patchState(store, updateEntity({ id: user.id, changes: user }));
      userService.updateUser(user as Omit<User, "token" | "password">).subscribe({
        next: (updatedUser) => {
          patchState(store, updateEntity({ id: updatedUser.id, changes: updatedUser }));
        },
        error: (err) => {
          patchState(store, updateEntity({ id: user.id, changes: originalUser }));
        },
      });
    },
    removeUser(userId: number) {
      const user = store.entities().find((u) => u.id === userId);
      if (!user) return;
      userService.deleteUser(user).subscribe({
        next: () => {
          patchState(store, removeEntity(userId));
        },
      });
    },
  })),
);
